        async content(event, trigger, player) {
            const name = event.cost_data.links[0];
            const effect = "nysgs_caochun_skill2_effect";
            game.log(player, "选择了", "#g" + "【" + get.translation(name) + "】");
            const list = player.getStorage(effect).filter(info => get.subtype(info) == get.subtype(name));
            if (list.length) player.unmarkAuto(effect, list);
            player.markAuto(effect, [name]);
            const addSkills = [];
            for (const card of player.getStorage(effect)) {
                const skills = lib.card[card]?.skills ?? [];
                const equipNum = get.equipNum(card);
                for (const from of skills) {
                    const skill = `${event.name}_${from}`;
                    if (!lib.skill[skill]) {
                        game.broadcastAll(
                            (skill, from, to) => {
                                lib.skill[skill] = get.copy(get.info(from));
                                const info = get.info(skill);
                                const infox = get.info(from);
                                info.nysgs_caochun_skill2_equipNum = to;
                                info.audio = from;
                                if (info.mod) {
                                    info.nysgs_caochun_skill2_mod = get.copy(info.mod);
                                    for (let name in info.mod) {
                                        const mod = function () {
                                            if (player.getEquips(this.nysgs_caochun_skill2_equipNum).length) return;
                                            return this.nysgs_caochun_skill2_mod[name].apply(this, arguments);
                                        };
                                        info.mod[name] = mod.bind(info);
                                    }
                                }
                                info.nysgs_caochun_skill2_filter = get.copy(infox.filter ?? lib.filter.all);
                                info.filter = function () {
                                    if (player.getEquips(this.nysgs_caochun_skill2_equipNum).length) return false;
                                    return this.nysgs_caochun_skill2_filter.apply(this, arguments);
                                }.bind(info);
                                lib.translate[skill] = lib.translate[from];
                                lib.translate[`${skill}_info`] = lib.translate[`${from}_info`];
                                game.finishSkill(skill);
                            },
                            skill,
                            from,
                            equipNum
                        );
                    }
                    addSkills.add(skill);
                }
            }
            player.addAdditionalSkill(event.name, addSkills);
            lib.skill[event.name].$addVirtualEquip(player, name, event.name);
        },
        $addVirtualEquip(player, name, skill) {
            const equipNum = get.equipNum(name);
            if (player.getEquips(equipNum).length) return;
            const card = game.createCard(name, "none", 0);
            card.fix();
            card.style.transform = "";
            card.classList.remove("drawinghidden");
            card.classList.add("emptyequip");
            delete card._transform;
            this.$removeVirtualEquip.apply(this, arguments);
            let equipped = false;
            for (let j = 0; j < player.node.equips.childNodes.length; j++) {
                if (get.equipNum(player.node.equips.childNodes[j]) >= equipNum) {
                    player.node.equips.insertBefore(card, player.node.equips.childNodes[j]);
                    equipped = true;
                    break;
                }
            }
            if (!equipped) {
                player.node.equips.appendChild(card);
            }
            player.$handleEquipChange();
        },
        $removeVirtualEquip(player, name, skill) {
            const equipNum = get.equipNum(name);
            for (let i = 0; i < player.node.equips.childNodes.length; i++) {
                const card = player.node.equips.childNodes[i];
                if (card.classList.contains("emptyequip") && get.equipNum(card) == equipNum) {
                    player.node.equips.removeChild(card);
                }
            }
        },
