    nysgs_dianwei_skill2: {
        nobracket: true,
        trigger: {
            player: "phaseJieshuBegin",
        },
        forced: true,
        limited: true,
        async content(event, trigger, player) {
            player.awakenSkill(event.name);
            const cards = [];
            for (let i = 0; i < 3; i++) {
                const card = get.cardPile(card => {
                    return get.type(card) == "equip" && !cards.includes(card);
                });
                if (card) cards.push(card);
            }
            if (!cards.length) return;
            game.cardsGotoOrdering(cards);
            const videoId = lib.status.videoId++;
            game.broadcastAll(
                (player, id, cards) => {
                    let str = "宛城护主";
                    if (player == game.me && !_status.auto) {
                        str += "：选择获得一张牌";
                    }
                    const dialog = ui.create.dialog(str, cards);
                    dialog.videoId = id;
                },
                player,
                videoId,
                cards
            );
            const time = get.utc();
            game.addVideo("showCards", player, ["宛城护主", get.cardsInfo(cards)]);
            game.addVideo("delay", null, 2);
            const next = player.chooseButton(true);
            next.set("dialog", event.videoId);
            next.set("ai", button => {
                return Math.max(get.value(button.link), get.useful(button.link));
            });
            const result = await next.forResult();
            if (result?.bool && result.links) {
                const time2 = 1000 - (get.utc() - time);
                if (time2 > 0) {
                    await game.delay(0, time2);
                }
                game.broadcastAll("closeDialog", videoId);
                await player.gain(result.links, "gain2");
            }
        },
    },
