    nysgs_jie_zhanghe_skill2: {
        nobracket: true,
        trigger: {
            player: "phaseAnyBefore",
        },
        filter(event, player) {
            return player.countCards("h") > 0;
        },
        async cost(event, trigger, player) {
            let check,
                str = "弃置一张手牌并跳过";
            str += get.translation(trigger.name);
            str += "，然后可以获得至多两名角色各一张手牌";
            switch (trigger.name) {
                case "phaseJudge":
                    check = player.countCards("j");
                    break;
                case "phaseDraw": {
                    let i,
                        num = 0,
                        num2 = 0;
                    const players = game.filterPlayer();
                    for (i = 0; i < players.length; i++) {
                        if (player != players[i] && players[i].countCards("h")) {
                            const att = get.attitude(player, players[i]);
                            if (att <= 0) {
                                num++;
                            }
                            if (att < 0) {
                                num2++;
                            }
                        }
                    }
                    check = num >= 2 && num2 > 0;
                    break;
                }
                case "phaseUse":
                    if (!player.canMoveCard(true)) {
                        check = false;
                    } else {
                        check = game.hasPlayer(function (current) {
                            return get.attitude(player, current) > 0 && current.countCards("j");
                        });
                        if (!check) {
                            if (player.countCards("h") > player.hp + 1) {
                                check = false;
                            } else if (player.countCards("h", { name: "wuzhong" })) {
                                check = false;
                            } else {
                                check = true;
                            }
                        }
                    }
                    break;
                case "phaseDiscard":
                    check = player.needsToDiscard();
                    break;
                default: 
                    check = true;
                    break;
            }
            event.result = await player
                .chooseToDiscard(get.prompt(event.skill), str, lib.filter.cardDiscardable)
                .set("ai", card => {
                    if (!_status.event.check) {
                        return -1;
                    }
                    return 7 - get.value(card);
                })
                .set("check", check)
                .forResult();
        },
        async content(event, trigger, player) {
            trigger.cancel();
            game.log(player, "跳过了", "#y" + get.translation(trigger.name));
            const result = await player
                .chooseTarget([1, 2], "获得至多两名角色各一张手牌", function (card, player, target) {
                    return target != player && target.countCards("h");
                })
                .set("ai", function (target) {
                    return 1 - get.attitude(_status.event.player, target);
                })
                .forResult();
            if (!result.bool) {
                return;
            }
            result.targets.sortBySeat();
            player.line(result.targets, "green");
            if (!result.targets.length) {
                return;
            }
            await player.gainMultiple(result.targets);
            await game.delay();
        },
        ai: {
            threaten: 3,
        },
    },
