    nysgs_ganfuren_skill3: {
        nobracket: true,
        trigger: {
            global: "useCardToPlayered",
        },
        popup: false,
        filter(event, player) {
            if (event.getParent().triggeredTargets3.length > 1) {
                return false;
            }
            return event.card.name == "sha" || get.is.singleCard(event.card);
        },
        async cost(event, trigger, player) {
            const list = ["令此牌效果+1", "令此牌无效"];
            list.push("cancel2");
            let eff = 0;
            if (trigger.card.name == "wuxie" || trigger.card.name == "shan") {
                if (get.attitude(player, trigger.player) < -1) {
                    eff = -1;
                }
            } else if (trigger.targets && trigger.targets.length) {
                for (var i = 0; i < trigger.targets.length; i++) {
                    eff += get.effect(trigger.targets[i], trigger.card, trigger.player, player);
                }
            }
            const result = await player
                .chooseControl(list)
                .set("prompt", get.prompt(event.skill, trigger.player))
                .set("ai", () => {
                    const { player, eff1, eff2 } = get.event();
                    if (player.getHp() + player.countCards("hs", card => player.canSaveCard(card, player)) <= 1) return 2;
                    if (eff2 < 0) return 1;
                    if (eff1 > 1) return 0;
                    return 2;
                })
                .set("eff1", trigger.targets.reduce((acc, target) => {
                    if (trigger.card.name === "tao" && target.getDamagedHp() < 2) {
                        return acc;
                    }
                    return acc + get.effect(target, trigger.card, trigger.player, player);
                }, 0))
                .set("eff2", eff)
                .forResult();
            if (result.index != 2) event.result = { bool: true, cost_data: { index: result.index } };
        },
        async content(event, trigger, player) {
            player.logSkill(event.name, trigger.player);
            await player.loseHp();
            if (event.cost_data.index == 0) {
                const backups = get.copy(get.info("_nysgsFury_buff").getBuff.get(trigger.card.name));
                const next = game.createEvent(`${event.name}_${trigger.card.name}`, false);
                next.player = player;
                next._trigger = trigger.getParent();
                next.num = 1;
                next.setContent(backups.content);
            } else {
                trigger.getParent().all_excluded = true;
                trigger.getParent().targets.length = 0;
            }
        },
    },
