    nysgs_huaman_skill: {
        audio: "ext:怒焰三国/audio/skill:2",
        trigger: {
            global: "phaseBegin",
        },
        popup: false,
        filter(event, player) {
            return player != event.player && player.countCards("h");
        },
        async cost(event, trigger, player) {
            const result = await player
                .chooseToDiscard("h", get.prompt2(event.skill, trigger.player), "chooseonly")
                .set("filterCard", card => {
                    const player = get.player();
                    return !player.hasStorage("nysgs_huaman_skill_used", card.name);
                })
                .set("ai", function (card) {
                    var player = _status.event.player,
                        target = _status.event.getTrigger().player;
                    var suit = get.suit(card, player),
                        list;
                    switch (suit) {
                        case "spade":
                            list = [{ name: "nanman" }, target, target];
                            break;
                        case "heart":
                            list = [{ name: "wuzhong" }, player, player];
                            break;
                        case "club":
                            list = [{ name: "tiesuo" }, player, target];
                            break;
                        case "diamond":
                            list = [{ name: "sha" }, player, target];
                            break;
                    }
                    list[0].isCard = true;
                    var eff = 0;
                    if (list[1].canUse(list[0], list[2], false)) {
                        eff = get.effect(list[2], list[0], list[1], player);
                    }
                    if (eff >= 0 || suit == "club") {
                        eff = Math.max(eff, 5);
                    }
                    return eff * 1.5 - get.value(card);
                })
                .forResult();
            if (result?.bool) {
                event.result = {
                    bool: true,
                    cards: result.cards,
                    targets: [trigger.player],
                };
            }
        },
        async content(event, trigger, player) {
            var target = trigger.player,
                card = event.cards[0],
                suit = get.suit(card, player);
            player.logSkill(event.name, target);
            await player.discard(event.cards);
            if (!lib.suit.includes(suit) || ((!target || !target.isIn()) && suit != "heart")) {
                return;
            }
            switch (suit) {
                case "spade": {
                    const next = player.chooseUseTarget({ name: "nanman", isCard: true }, true);
                    next.set("oncard", function (card, player) {
                        _status.event.nysgsFuryBuff = true;
                    });
                    await next;
                }
                    break;
                case "heart": {
                    const cards = [];
                    for (var i = 0; i < 3; i++) {
                        var card = get.cardPile2(function (card) {
                            return !cards.reduce((list, cardx) => list.add(get.suit(cardx)), []).includes(get.suit(card));
                        });
                        if (card) {
                            cards.push(card);
                        }
                    }
                    if (cards.length) {
                        await player.gain(cards, "gain2");
                    }
                }
                    break;
                case "club": {
                    const cards = target.getCards("h", card => {
                        return lib.filter.cardDiscardable(card, player, "nysgs_huaman_skill");
                    });
                    if (cards.length > 0) {
                        const evt = target.discard(cards.randomGets(2)).set("discarder", player);
                        await evt;
                    }
                }
                    break;
                case "diamond": {
                    if (player.canUse({ name: "sha", isCard: true }, target, false)) {
                        const next = player.useCard({ name: "sha", isCard: true }, target, false);
                        next.nysgsFuryBuff = true;
                        await next;
                    }
                }
                    break;
            }
            player.addTempSkill("nysgs_huaman_skill_used");
            player.markAuto("nysgs_huaman_skill_used", event.cards.reduce((list, card) => list.add(card.name), []));
            if (!player.hasSkill("nysgs_huaman_skill3")) return;
            event.skill = "nysgs_huaman_skill";
            await get.info("nysgs_huaman_skill").cost(event, trigger, player);
            if (event.result) {
                event.result.name = "nysgs_huaman_skill";
                await get.info("nysgs_huaman_skill").content(event.result, trigger, player);
            }
        },
        mod: {
            cardEnabled(card, player) {
                if (player.hasSkill("nysgs_huaman_skill3")) {
                    return;
                }
                if (player === _status.currentPhase && get.is.damageCard(card)) {
                    return false;
                }
            },
            cardSavable(card, player) {
                if (player.hasSkill("nysgs_huaman_skill3")) {
                    return;
                }
                if (player === _status.currentPhase && get.is.damageCard(card)) {
                    return false;
                }
            },
        },
        ai: {
            halfneg: true,
            skillTagFilter(player, tag, arg) {
                if (player.hasSkill("nysgs_huaman_skill3")) {
                    return false;
                }
            },
        },
        subSkill: {
            used: {
                charlotte: true,
                onremove: true,
            },
        },
    },
