    nysgs_zhugezhan_skill: {
        audio: "ext:怒焰三国/audio/skill:2",
        trigger: {
            global: "phaseEnd",
        },
        forced: true,
        getNum(player) {
            let num = 0;
            if (player.hasHistory("sourceDamage")) {
                num++;
            }
            if (
                !player.hasHistory("lose", function (evt) {
                    return evt.type == "discard";
                })
            ) {
                num++;
            }
            if (
                !player.hasHistory("lose", function (evt) {
                    return evt.hs?.length;
                })
            ) {
                num++;
            }
            return num;
        },
        async content(event, trigger, player) {
            const num = lib.skill.nysgs_zhugezhan_skill.getNum(player);
            if (num == 3) {
                await player.draw(3);
                return;
            } else if (num > 0) {
                await player.draw(num);
            }
            const num2 = (3 - num) * 2;
            const result = await player
                .chooseTarget(`你发动了【${get.translation(event.name)}】`, `选择一名其他角色，你与其各流失${num2}点体力`, true)
                .set("filterTarget", (card, player, target) => {
                    return target != player && target.getHp(true) > 0;
                })
                .set("ai", target => {
                    const player = get.player();
                    return get.effect(target, { name: "losehp" }, player, player);
                })
                .forResult();
            if (result?.bool) {
                player.line(result.targets);
                //诸葛瞻的对手先流失体力
                for (const target of result.targets.slice().add(player)) {
                    const next = target.loseHp(num2);
                    next.set("source", player);
                    await next;
                }
            }
        },
    },
