            if (_status.nysgs_stratagem) return;
            _status.nysgs_stratagem = true;
            const list = lib.skill.nysgs_puyuan_skill.getList;
            for (const name of list) {
                const info = lib.card[name];
                //【白银狮子】特殊处理
                //if (!info.skills) info.skills = [];
                //if (!Array.isArray(info.skills)) info.skills = [info.skills];
                //info.skills.add(`nysgs_stratagem_${name}`);
                if (!info.global) info.global = [];
                if (!Array.isArray(info.global)) info.global = [info.global];
                info.global.add(`nysgs_stratagem_${name}`);
                if (info.nysgs_stratagem_prompt) continue;
                info.nysgs_stratagem_prompt = true;
                if (info.cardPrompt) {
                    info.nysgs_stratagem_cardprompt = get.copy(info.cardPrompt);
                }
                info.cardPrompt = function (card, player) {
                    var str = "", name, info;
                    if (Array.isArray(card)) {
                        name = card[2];
                    } else {
                        name = card.name;
                    }
                    info = get.info({ name: name });
                    if (info.nysgs_stratagem_cardprompt) {
                        str += info.nysgs_stratagem_cardprompt(card, player);
                    } else {
                        str += lib.translate[`${name}_info`];
                    }
                    if (card) {
                        let vcard = card[card.cardSymbol];
                        if (vcard?.storage?.nysgs_stratagem) {
                            str += `<br><span style="font-family:yuanli">强化：${lib.translate[`nysgs_stratagem_${name}_info`]}</span>`;
                        }
                    }
                    return str;
                };
            }
