    nysgs_jie_sunquan_skill2: {
        nobracket: true,
        nobracket: true,
        trigger: {
            player: "nysgs_jie_sunquan_skillBegin",
        },
        forced: true,
        locked: false,
        getList() {
            let list;
            if (_status.characterlist) {
                list = [];
                for (let i = 0; i < _status.characterlist.length; i++) {
                    const name = _status.characterlist[i];
                    if (lib.character[name][1] == "wu") {
                        list.push(name);
                    }
                }
            } else if (_status.connectMode) {
                list = get.charactersOL(function (i) {
                    return lib.character[i][1] != "wu";
                });
            } else {
                list = get.gainableCharacters(function (info) {
                    return info[1] == "wu";
                });
            }
            const players = game.players.concat(game.dead);
            for (let i = 0; i < players.length; i++) {
                list.remove(players[i].name);
                list.remove(players[i].name1);
                list.remove(players[i].name2);
            }
            list.removeArray(lib.skill.nysgs_jie_sunquan_skill2.banList);
            const filter = skill => {
                const translation = get.skillInfoTranslation(skill);
                if (!translation) return false;
                const info = get.info(skill);
                return info && !info.charlotte;
            };
            list = list.filter(name => (lib.character[name][3] || []).some(filter));
            return list;
        },
        banList: [],
        async content(event, trigger, player) {
            if (!trigger.num || typeof trigger.num != "number") {
                trigger.num = 0;
            }
            trigger.num += 2;
            const next = game.createEvent(event.name + "_addSkill", false);
            next.player = player;
            next.setContent(lib.skill.nysgs_jie_sunquan_skill2.contentx);
            event.next.remove(next);
            trigger.after.push(next);
        },
        async contentx(event, trigger, player) {
            const list = lib.skill.nysgs_jie_sunquan_skill2.getList().randomGets(3);
            const skills = [];
            for (const i of list) {
                skills.addArray(
                    (lib.character[i][3] || []).filter(function (skill) {
                        const info = get.info(skill);
                        return info && !info.zhuSkill && !info.limited && !info.juexingji && !info.hiddenSkill && !info.charlotte && !info.dutySkill;
                    }).slice(0, 1)
                );
            }
            if (!list.length) {
                return;
            }
            const videoId = lib.status.videoId++;
            const createDialog = function (list, skills, id) {
                let dialog = ui.create.dialog("###江东柱石###", [list, "character"]);
                if (list.length > 6) {
                    const width = list.length * (lib.config["extension_十周年UI_enable"] ? 150 : 125);
                    dialog.style.setProperty("width", (width + "px"), "important");
                    dialog.style.setProperty("left", `calc(50% - ${(width / 2)}px)`, "important");
                }
                dialog.add([skills.map(skill => [skill, get.translation(skill)]), "tdnodes"]);
                const width = Math.max(...dialog.buttons.map(button => button.getBoundingClientRect().width));
                dialog.buttons.forEach(button => {
                    if (!list.includes(button.link)) {
                        button.style.setProperty("width", `${width}px`, "important");
                        if (lib.config["extension_十周年UI_enable"]) {
                            const margin = "20px";
                            button.style.setProperty("margin-left", margin, "important");
                            button.style.setProperty("margin-right", margin, "important");
                        }
                    } else {
                        button.style.setProperty("opacity", "1", "important");
                    }
                });
                dialog.videoId = id;

                dialog.style.display = "none";
                return dialog;
            }
            if (player.isOnline()) {
                player.send(createDialog, list, skills, videoId);
            } else {
                createDialog(list, skills, videoId);
            }
            const result = await player
                .chooseButton(get.idDialog(videoId))
                .set("filterButton", button => {
                    return !button.classList.contains("character");
                })
                .set("ai", button => {
                    const skill = button.link;
                    return get.skillRank(skill, "inout");
                })
                .forResult();
            game.broadcastAll("closeDialog", videoId);
            if (result?.links?.length) {
                await player.addTempSkills(result.links, { player: "phaseBegin" });
            }
        },
    },
