    nysgs_qi_dongzhuo_fenluo: {
        audio: "olbaonue",
        enable: "phaseUse",
        filter(event, player) {
            return player.nysgsCountFury() >= 2;
        },
        filterTarget: true,
        selectTarget: -1,
        multitarget: true,
        multiline: true,
        line: "fire",
        async content(event, trigger, player) {
            player.nysgsRemoveFury(2);
            let num = 1;
            let targets = event.targets.sortBySeat(player);
            for (const target of targets) {
                if (target.isIn()) {
                    player.line(target, "fire");
                    const prompt = target == player ?
                        `焚雒：你可以弃置任意张牌` : `焚雒：弃置至少${get.cnNumber(num)}张牌，或受到2点火焰伤害`;
                    const result = await target
                        .chooseToDiscard("he", prompt, [num, Infinity])
                        .set("ai", card => {
                            if (ui.selected.cards.length >= get.event().num) {
                                return -1;
                            }
                            if (get.player() == get.event().getParent().player || get.player().hasSkillTag("nofire")) {
                                return -1;
                            }
                            if (get.event().res >= 0) {
                                return 6 - get.value(card);
                            }
                            if (get.type(card) != "basic") {
                                return 10 - get.value(card);
                            }
                            return 8 - get.value(card);
                        })
                        .set("num", num)
                        .set("res", get.damageEffect(target, player, target, "fire"))
                        .forResult();
                    if (!result.bool) {
                        if (target != player) {
                            await target.damage(2, "fire");
                        }
                        num = 1;
                    } else {
                        num += result.cards.length;
                    }
                }
            }
        },
        ai: {
            order: 1,
            result: {
                player(player) {
                    var num = 0,
                        eff = 0,
                        players = game
                            .filterPlayer(function (current) {
                                return current != player;
                            })
                            .sortBySeat(player);
                    for (var target of players) {
                        if (get.damageEffect(target, player, target, "fire") >= 0) {
                            num = 0;
                            continue;
                        }
                        var shao = false;
                        num++;
                        if (
                            target.countCards("he", function (card) {
                                if (get.type(card) != "basic") {
                                    return get.value(card) < 10;
                                }
                                return get.value(card) < 8;
                            }) < num
                        ) {
                            shao = true;
                        }
                        if (shao) {
                            eff -= 4 * (get.realAttitude || get.attitude)(player, target);
                            num = 0;
                        } else {
                            eff -= (num * (get.realAttitude || get.attitude)(player, target)) / 4;
                        }
                    }
                    if (eff < 4) {
                        return 0;
                    }
                    return eff;
                },
            },
        },
    },
